namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "New comment on your pull request",
        "Build succeeded for main branch",
        "Deployment completed to production",
        "Code review requested by teammate",
        "Issue #{{id}} was assigned to you",
        "Pipeline failed — check logs",
        "New release v{{id}}.0 published",
        "Security alert: dependency update available"
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        var initial = new List<Notification>();
        lock (_lock)
        {
            for (var i = 0; i < 3; i++)
            {
                initial.Add(MakeNotification());
            }
        }
        return Task.FromResult(initial);
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        // Simulate: ~40% chance a new notification arrives each poll
        var results = new List<Notification>();
        if (Random.Shared.Next(5) < 2)
        {
            lock (_lock)
            {
                results.Add(MakeNotification());
            }
        }
        return Task.FromResult(results);
    }

    private Notification MakeNotification()
    {
        var id = _nextId++;
        var template = _templates[Random.Shared.Next(_templates.Length)];
        return new Notification
        {
            Id = id,
            Message = template.Replace("{{id}}", id.ToString()),
            Timestamp = DateTime.UtcNow
        };
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

@if (Items is null)
{
    <p>Loading…</p>
}
else
{
    <p>
        <span class="badge bg-primary rounded-pill">@Items.Count</span>
        notification@(Items.Count == 1 ? "" : "s")
    </p>

    <ul class="list-group">
        @foreach (var n in Items)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch data that was persisted from prerender
        Items ??= await NotificationSvc.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender never runs during prerender, so this is safe
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newItems = await NotificationSvc.CheckForNewNotificationsAsync();
            if (newItems.Count > 0)
            {
                Items!.InsertRange(0, newItems);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

