namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "New comment on your pull request",
        "Build succeeded for main branch",
        "Deployment completed to production",
        "Code review requested by teammate",
        "Issue #{{id}} was assigned to you",
        "Pipeline failed — check logs",
        "New release v{{id}}.0 published",
        "Security alert: dependency update available"
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        var initial = new List<Notification>();
        lock (_lock)
        {
            for (var i = 0; i < 3; i++)
            {
                initial.Add(MakeNotification());
            }
        }
        return Task.FromResult(initial);
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        // ~40% chance a new notification arrives each poll
        var results = new List<Notification>();
        if (Random.Shared.Next(5) < 2)
        {
            lock (_lock)
            {
                results.Add(MakeNotification());
            }
        }
        return Task.FromResult(results);
    }

    private Notification MakeNotification()
    {
        var id = _nextId++;
        var template = _templates[Random.Shared.Next(_templates.Length)];
        return new Notification
        {
            Id = id,
            Message = template.Replace("{{id}}", id.ToString()),
            Timestamp = DateTime.UtcNow
        };
    }
}

